/// Register one canonical wire tag independently of the C++ type spelling.
/// Use once in a .cpp. The unique identifier allows fully qualified type names;
/// it is only a registration-variable name, not another serialization alias.
#define CH_FACTORY_REGISTER_TAG(classname, archive_tag, uniquetag)                       \
    namespace class_factory {                                                            \
    static ::chrono::ChClassRegistration<classname> uniquetag##_factory_registration(archive_tag); \
    }

/// \brief Initialization of pointer up-casting functions

/// Preserve source/destination wire identities when their C++ types are renamed.
/// Use once per conversion in a .cpp; both tags must match the canonical graph.
#define CH_UPCASTING_TAGGED(FROM, TO, FROM_TAG, TO_TAG, UNIQUETAG)                                      \
    namespace class_factory {                                                                         \
    static ::chrono::ChCastingMap convfun_from_##UNIQUETAG(                                             \
        std::string(FROM_TAG), std::type_index(typeid(FROM*)),                                          \
        std::string(TO_TAG), std::type_index(typeid(TO*)),                                              \
        [](void* vptr) { return static_cast<void*>(static_cast<TO*>(reinterpret_cast<FROM*>(vptr))); }, \
        [](std::shared_ptr<void> vptr) {                                                               \
            return std::static_pointer_cast<void>(std::static_pointer_cast<TO>(std::static_pointer_cast<FROM>(vptr))); \
        });                                                                                           \
    }

// Class version registration

bool use_versions;

// Transient per-call wire name. Owned values avoid borrowed stack pointers
// in archive copies. Neither field is part of the serialized representation.
std::string version_name_override;
std::type_index version_name_type = std::type_index(typeid(void));

struct ChApi VersionNameScope {
    VersionNameScope(ChArchive& archive, std::type_index type, const char* name);
    ~VersionNameScope() noexcept;
    VersionNameScope(const VersionNameScope&) = delete;
    VersionNameScope& operator=(const VersionNameScope&) = delete;

  private:
    ChArchive& owner;
    std::string previous_name;
    std::type_index previous_type;
};

std::string VersionClassName(std::type_index type) const;

  /// Preserve a captured version identity for a renamed, unregistered type.
  /// Registered types normally use their canonical factory tag instead.
  /// Version policy and format-specific virtual hooks are unchanged.
  template <class T>
  void VersionWrite(const char* archive_type_name) {
      if (!use_versions)
          return;
      VersionNameScope name_scope(*this, std::type_index(typeid(T)), archive_type_name);
      this->VersionWrite<T>();
  }

protected:
  virtual void out_version(int mver, const std::type_index mtypeid);

  /// Read the same captured identity used by the named VersionWrite overload.
  /// The existing clustering, disabled-version and virtual-hook policy applies.
  template <class T>
  int VersionRead(const char* archive_type_name) {
      if (!use_versions)
          return 99999;
      VersionNameScope name_scope(*this, std::type_index(typeid(T)), archive_type_name);
      return this->VersionRead<T>();
  }

protected:
  virtual int in_version(const std::type_index mtypeid);

namespace chrono {

ChArchive::VersionNameScope::VersionNameScope(ChArchive& archive, std::type_index type, const char* name)
    : owner(archive), previous_type(archive.version_name_type) {
    if (!name || !*name)
        throw std::invalid_argument("An explicit archive version identity must not be empty");
    // Allocate before mutating the owner; all subsequent swaps are nonthrowing.
    std::string explicit_name(name);
    previous_name.swap(owner.version_name_override);
    explicit_name.swap(owner.version_name_override);
    owner.version_name_type = type;
}

ChArchive::VersionNameScope::~VersionNameScope() noexcept {
    previous_name.swap(owner.version_name_override);
    owner.version_name_type = previous_type;
}

std::string ChArchive::VersionClassName(std::type_index type) const {
    if (!version_name_override.empty() && version_name_type == type)
        return version_name_override;
    return ChClassFactory::IsClassRegistered(type) ? ChClassFactory::GetClassTagName(type) : std::string(type.name());
}

